import { test, expect } from '@playwright/test'
import { AxeBuilder } from '@axe-core/playwright'

test.describe('Trail Runner 2 product page', () => {
  test('is reachable at /products/trail-runner-2', async ({ page }) => {
    const response = await page.goto('/products/trail-runner-2')

    expect(response.ok()).toBeTruthy()
    await expect(page.getByText('Page not found.')).not.toBeVisible()
  })

  test('has no accessibility violations', async ({ page }) => {
    await page.goto('/products/trail-runner-2')

    const results = await new AxeBuilder({ page })
      .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'best-practice'])
      .analyze()

    expect(results.violations).toEqual([])
  })
})

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import HomePage from './pages/HomePage.jsx'

const pages = {
  '/': HomePage,
}

const Page = pages[window.location.pathname] ?? (() => <p>Page not found.</p>)

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <Page />
  </StrictMode>,
)

export default function HomePage() {
  return (
    <div>
      <h1>Stride</h1>
      <p>Shoes for every trail.</p>
      <a href="/products/trail-runner-2">Trail Runner 2</a>
    </div>
  )
}

