  display: flex;
  gap: 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.main-menu a {
  color: #1a1a1a;
  text-decoration: none;
  font-weight: 500;
}

.main-menu a:hover {
  text-decoration: underline;
}

.cart-status {
  margin: 0 0 0 auto;
  font-weight: 600;
}

